// Check kill switch
const benchmarkRows = $input.all().map(i => i.json);
const killSwitch = benchmarkRows.find(r => r.metric === 'agent_paused');
if (killSwitch && String(killSwitch.benchmark_daily_green).toLowerCase() === 'true') {
  return [{ json: { skip: true, reason: 'agent_paused = true in config' } }];
}

// Build data JSON từ Dashboard sheet (giả sử sheet có cột: metric_group, metric, mtd, d_1, d_2)
// LƯU Ý: Cấu trúc sheet thực tế có thể khác — cần map lại theo sheet của Hecatech
const dashboardRows = $('Read Dashboard XKMVN').all().map(i => i.json);

function findMetric(group, metric) {
  const row = dashboardRows.find(r => r.metric_group === group && r.metric === metric);
  return row ? { mtd: Number(row.mtd), d_1: Number(row.d_1), d_2: Number(row.d_2) } : null;
}

const today = new Date();
const yesterday = new Date(today.getTime() - 86400000);
const dateStr = yesterday.toISOString().slice(0, 10);
const dayOfMonth = yesterday.getDate();
const daysInMonth = new Date(yesterday.getFullYear(), yesterday.getMonth() + 1, 0).getDate();

const metaRows = benchmarkRows.filter(r => r.metric_group === '_META');
const meta = Object.fromEntries(metaRows.map(r => [r.metric, r.benchmark_daily_green]));

const data = {
  project: 'XKMVN',
  date: dateStr,
  day_of_month: dayOfMonth,
  days_in_month: daysInMonth,
  is_mega_day: false,  // TODO: đọc từ sheet lịch sự kiện
  has_live: String(meta.has_live).toUpperCase() === 'TRUE',
  has_affiliate: String(meta.has_affiliate).toUpperCase() === 'TRUE',
  status: meta.status || 'scale',
  A_doanh_so: {
    tong_gmv: findMetric('A. Doanh số', 'Tổng GMV'),
    gmv_livestream: findMetric('A. Doanh số', 'GMV Livestream'),
    gmv_video: findMetric('A. Doanh số', 'GMV Video'),
    gmv_the_sp: findMetric('A. Doanh số', 'GMV Thẻ SP')
  },
  C_ads: {
    take_rate: findMetric('C. Ads', 'Take Rate'),
    roas: findMetric('C. Ads', 'ROAS'),
    ctr_qc: findMetric('C. Ads', 'CTR QC'),
    cvr_qc: findMetric('C. Ads', 'CVR QC'),
    cpa: findMetric('C. Ads', 'CPA'),
    impressions: findMetric('C. Ads', 'Impressions'),
    chi_phi_qc: findMetric('C. Ads', 'Chi phí QC'),
    gmv_ads: findMetric('C. Ads', 'GMV Ads')
  },
  F_van_hanh: {
    ty_le_huy: findMetric('F. Vận hành', 'Tỷ lệ hủy'),
    ty_le_hoan: findMetric('F. Vận hành', 'Tỷ lệ hoàn')
  },
  G_pl: {
    net_profit_margin: findMetric('G. P&L', 'Net Profit Margin'),
    loi_nhuan_rong: findMetric('G. P&L', 'Lợi nhuận ròng')
  }
  // TODO: thêm B_livestream, D_product_card, E_affiliate khi map xong sheet structure
};

return [{ json: { data, benchmark: benchmarkRows.filter(r => r.metric_group !== '_META') } }];

