// Parse Claude JSON response
const response = $json;
let text = response.content[0].text.trim();

// Strip markdown code fences
text = text.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '');

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  throw new Error('Claude did not return valid JSON: ' + e.message + '\nRaw: ' + text.slice(0, 500));
}

// Build Lark interactive card
const emoji = { green: '✅', yellow: '🟡', red: '🔴' };
const warnings = parsed.warnings || [];
const spots = parsed.bright_spots || [];
const actions = parsed.top_actions_today || [];
const flags = parsed.data_quality_flags || [];

let content = '';
const s = parsed.summary || {};

content += '**📊 TỔNG QUAN**\n';
if (s.gmv_yesterday) {
  content += `GMV hôm qua: **${(s.gmv_yesterday.value/1e6).toFixed(0)}M** ${emoji[s.gmv_yesterday.status] || ''}`;
  if (s.gmv_yesterday.vs_benchmark_daily) content += ` (vs daily: ${s.gmv_yesterday.vs_benchmark_daily})`;
  content += '\n';
}
if (s.gmv_mtd) {
  content += `MTD: ${(s.gmv_mtd.value/1e9).toFixed(2)}B / ${(s.gmv_mtd.target/1e9).toFixed(1)}B (${s.gmv_mtd.pct}% — ${s.gmv_mtd.pacing_status})\n`;
}
if (s.net_profit_margin_mtd) {
  content += `Net margin MTD: ${(s.net_profit_margin_mtd.value*100).toFixed(1)}% ${emoji[s.net_profit_margin_mtd.status] || ''}\n`;
}
content += '\n';

if (warnings.length > 0) {
  content += `**⚠️ WARNING (${warnings.length} chỉ số)**\n\n`;
  for (const w of warnings) {
    const streak = w.consecutive_days > 1 ? ` — ngày thứ ${w.consecutive_days}` : '';
    content += `**${w.priority}. ${emoji[w.status]} ${w.metric}: ${w.value}**${streak}\n`;
    content += `   ↳ Ngưỡng: ${w.threshold}\n`;
    content += `   ↳ Nguyên nhân: ${w.root_cause}\n`;
    content += `   ↳ Hành động: ${w.action}\n`;
    content += `   ↳ Owner: ${w.owner}\n`;
    if (w.missing_data_note) content += `   ℹ️ ${w.missing_data_note}\n`;
    content += '\n';
  }
}

if (spots.length > 0) {
  content += '**✅ ĐIỂM SÁNG**\n';
  for (const b of spots) content += `- ${b.metric}: ${b.value} (${b.note})\n`;
  content += '\n';
}

if (actions.length > 0) {
  content += '**📋 TOP VIỆC HÔM NAY**\n';
  for (const a of actions) content += `${a.priority}. ${a.action} — ${a.owner}\n`;
  content += '\n';
}

if (flags.length > 0) {
  content += '**⚙️ DATA NOTES**\n' + flags.map(f => `- ${f}`).join('\n');
}

const hasRed = warnings.some(w => w.status === 'red');
const headerTemplate = hasRed ? 'red' : (warnings.length > 0 ? 'yellow' : 'green');

const larkCard = {
  msg_type: 'interactive',
  card: {
    header: {
      title: { tag: 'plain_text', content: `${parsed.project} — ${parsed.date}` },
      template: headerTemplate
    },
    elements: [
      { tag: 'markdown', content }
    ]
  }
};

return [{ json: { larkCard, parsed, should_send: warnings.length > 0 } }];
